mapper.select:
SELECT TECH , OPE_NO,STD_SR,UPDATE_USER,UPDATE_TIME FROM A1MFG.DOWNSAMPLING_TARGET_SR WHERE 1=1
AND TECH = #{tech,jdbcType=VARCHAR}
AND OPE_NO LIKE '%'|| #{opeNo,jdbcType=VARCHAR}||'%'

mapper.insert:
INSERT INTO A1MFG.DOWNSAMPLING_JURGE_HISTORY(PRODG1,PRODSPEC_ID,OPE_NO,EQP_G,MODULE,CUR_SR,STD_SR,UPLOAD_STD_TIME,JURGE_RESULT,UPDATE_TIME,UPDATE_USER) SELECT A.PRODG1,A.PRODSPEC_ID,A.OPE_NO,B.EQP_G,A.MODULE,A.SR CUR_SR,A.STD_SR,D.UPDATE_TIME UPLOAD_STD_TIME,A.JURGE_RESULT,A.UPDATE_TIME,A.UPDATE_USER FROM(
SELECT #{item.prodg1,jdbcType=VARCHAR} PRODG1,#{item.prodspecId,jdbcType=VARCHAR} PRODSPEC_ID,#{item.opeNo,jdbcType=VARCHAR} OPE_NO ,#{item.module,jdbcType=VARCHAR} MODULE,#{item.sr,jdbcType=DOUBLE} SR ,#{item.stdSr,jdbcType=DOUBLE} STD_SR,#{item.jurgeResult,jdbcType=VARCHAR} JURGE_RESULT,SYSDATE UPDATE_TIME,#{item.updateUser,jdbcType=VARCHAR} UPDATE_USER FROM DUAL
)A LEFT JOIN A1MFG.DOWNSAMPLING_MOVE_HISTORY B ON A.PRODG1 = B.PRODG1 AND A.OPE_NO = B.OPE_NO LEFT JOIN A1MFG.PRODUCT_TECH_INFO C ON A.PRODG1 = C.PRODG1 LEFT JOIN A1MFG.DOWNSAMPLING_TARGET_SR D ON C.MFG_TECH = D.TECH AND A.OPE_NO = D.OPE_NO

MERGE INTO A1MFG.DOWNSAMPLING_TARGET_SR A USING ( SELECT A.TECH,B.OPE_NO ,CASE WHEN B.STD_SR = 0 THEN 0 ELSE 1/B.STD_SR END STD_SR,B.UPDATE_USER,SYSDATE UPDATE_TIME FROM( SELECT DISTINCT MFG_TECH TECH FROM A1MFG.PRODUCT_TECH_INFO )A JOIN(
SELECT TRIM(#{item.tech,jdbcType=VARCHAR}) TECH, TRIM(#{item.opeNo,jdbcType=VARCHAR}) OPE_NO, #{item.stdSR,jdbcType=DOUBLE} STD_SR, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER FROM DUAL
)B ON A.TECH = B.TECH ) B ON (A.TECH = B.TECH AND A.OPE_NO = B.OPE_NO) WHEN MATCHED THEN UPDATE SET A.STD_SR = B.STD_SR, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = SYSDATE WHEN NOT MATCHED THEN INSERT (TECH, OPE_NO, STD_SR, UPDATE_USER, UPDATE_TIME) VALUES (B.TECH, B.OPE_NO, B.STD_SR, B.UPDATE_USER, SYSDATE)
